def _list_to_tree(lst):
    if not lst or lst[0] is None:
        return None
    root = TreeNode(lst[0])
    queue = [root]
    i = 1
    while queue and i < len(lst):
        curr = queue.pop(0)
        if i < len(lst) and lst[i] is not None:
            curr.left = TreeNode(lst[i])
            queue.append(curr.left)
        i += 1
        if i < len(lst) and lst[i] is not None:
            curr.right = TreeNode(lst[i])
            queue.append(curr.right)
        i += 1
    return root

def generate(rng, n):
    if n <= 0:
        return [None]
    vals = [rng.randint(-100, 100) for _ in range(n)]
    return [_list_to_tree(vals)]

def generate_worst(rng, n):
    if n <= 0:
        return [None]
    root = TreeNode(rng.randint(-100, 100))
    curr = root
    for _ in range(n - 1):
        curr.left = TreeNode(rng.randint(-100, 100))
        curr = curr.left
    return [root]

